commit 0e0421cfe2b3e22bd5f0a1bb72cefef67cae6aa5
Author: Philip Withnall <pwithnall@gnome.org>
Date:   Tue Oct 22 13:18:59 2024 +0100

    fuzzing: Fix buffer overread error in the fuzz test itself

    valgrind spotted this one: a read off the end of the `stop_chars` buffer
    when `stop_chars_len == -1`, due to the fuzzing test not sticking to the
    requirement from `g_data_input_stream_read_upto()` that `stop_chars`
    must be nul-terminated if `stop_chars_len < 0`.

    This can happen when reading `fuzzing/README.md`, which is done as a
    smoketest when the fuzzing tests are run without the fuzzer, as normal
    unit tests. In this case, it made smoke.

    Signed-off-by: Philip Withnall <pwithnall@gnome.org>

diff --git a/fuzzing/fuzz_data_input_stream_read_upto.c b/fuzzing/fuzz_data_input_stream_read_upto.c
index 0c66f04a4..eedb9ba00 100644
--- a/fuzzing/fuzz_data_input_stream_read_upto.c
+++ b/fuzzing/fuzz_data_input_stream_read_upto.c
@@ -28,7 +28,8 @@ LLVMFuzzerTestOneInput (const unsigned char *data, size_t size)
   size_t line_length = 0;
   const unsigned char *separator, *first_nul;
   const unsigned char *stop_chars;
-  size_t stop_chars_len;
+  unsigned char *owned_stop_chars = NULL;
+  gssize stop_chars_len;
   const unsigned char *stream_data;
   size_t stream_data_len;

@@ -60,6 +61,10 @@ LLVMFuzzerTestOneInput (const unsigned char *data, size_t size)
       stream_data_len = size - (separator + 1 - data);
     }

+  /* If stop_chars_len < 0, we have to guarantee that it’s nul-terminated. */
+  if (stop_chars_len < 0)
+    stop_chars = owned_stop_chars = (unsigned char *) g_strndup ((const char *) stop_chars, separator - data);
+
   /* Build the stream and test read_upto(). */
   base_stream = g_memory_input_stream_new_from_data (stream_data, stream_data_len, NULL);
   input_stream = g_data_input_stream_new (base_stream);
@@ -69,6 +74,7 @@ LLVMFuzzerTestOneInput (const unsigned char *data, size_t size)
   g_assert (line_length <= size);
   g_free (line);

+  g_free (owned_stop_chars);
   g_clear_object (&input_stream);
   g_clear_object (&base_stream);
